ee:message.ee:set-payload:
%dw 2.0
output application/json
import util::GlobalFunctions as global
---
{
    orderOM: payload.ordenOM,
	items: payload.productos map (value, index) -> {
        (idItem: value.idItem) if (upper(payload.proceso) == upper("actualizarEstadoSolicitud") or upper(payload.proceso) == upper("actualizarGrupoPropietario") or upper(payload.proceso) == upper("CierreAprovisionamiento") or upper(payload.proceso) == upper("actualizarFechaAgenda")),
        (parentId: value.idRaiz) if (upper(payload.proceso) == upper("actualizarEstadoSolicitud") or upper(payload.proceso) == upper("actualizarGrupoPropietario") or upper(payload.proceso) == upper("CierreAprovisionamiento") or upper(payload.proceso) == upper("actualizarFechaAgenda")),
        (engineer: payload.responsable)  if (upper(payload.proceso) == upper("actualizarGrupoPropietario") or upper(payload.proceso) == upper("actualizarEstadoSolicitud")),
        (faseGestor: payload.faseSolicitud) if (upper(payload.proceso) == upper("actualizarEstadoSolicitud") or upper(payload.proceso) == upper("CierreAprovisionamiento")),
        (groupAssigment: payload.grupoAsignacion)  if (upper(payload.proceso) == upper("actualizarGrupoPropietario") or upper(payload.proceso) == upper("actualizarEstadoSolicitud")),
        (fechaAsignacionResponsable: now() >> "America/Bogota") if (upper(payload.proceso) == upper("actualizarEstadoSolicitud") or upper(payload.proceso) == upper("CierreAprovisionamiento") or upper(payload.proceso) == upper("ActualizarGrupoPropietario")),
        (statusProvisioning: payload.estadoSolicitud) if (upper(payload.proceso) == upper("actualizarEstadoSolicitud") or upper(payload.proceso) == upper("CierreAprovisionamiento")),
        (statusGestor: payload.estadoGestor) if (upper(payload.proceso) == upper("actualizarEstadoSolicitud") or upper(payload.proceso) == upper("CierreAprovisionamiento")),
        (comments: payload.respuestaGestor) if (upper(payload.proceso) == upper("actualizarEstadoSolicitud") or upper(payload.proceso) == upper("CierreAprovisionamiento")),
        (causalFinalizacionSolicitud: payload.causalFinalizacionSolicitud) if (upper(payload.proceso) == upper("CierreAprovisionamiento")),
        (provisioningDate: global::formatDate(payload.fechaProcesamiento) default null) if (upper(payload.proceso) == upper("actualizarEstadoSolicitud") or upper(payload.proceso) == upper("actualizarGrupoPropietario") or upper(payload.proceso) == upper("CierreAprovisionamiento") or upper(payload.proceso) == upper("actualizarFechaAgenda")),
        (agendamiento: {
            agendaDate: global::formatDate(payload.agendamiento.fechaAgenda) default null,
            agendaStrip: payload.agendamiento.franjaAgenda,
            agendaStatus: payload.agendamiento.estadoAgenda,
        }) if (upper(payload.proceso) == upper("actualizarFechaAgenda")),
        listaConfiguraciones: value.parametros map (val, ind) ->{
            parametros: {
                (atributo: val.nombre) if (upper(payload.proceso) == upper("actualizarEstadoSolicitud") or upper(payload.proceso) == upper("actualizarGrupoPropietario") or upper(payload.proceso) == upper("CierreAprovisionamiento")),
                (valor: val.valor) if (upper(payload.proceso) == upper("actualizarEstadoSolicitud") or upper(payload.proceso) == upper("actualizarGrupoPropietario") or upper(payload.proceso) == upper("CierreAprovisionamiento"))
            }
        }

    }
}
